# hdWGCNA single-cell co-expression modules on Zeisel cortex/hippocampus (metacells per cell type)
suppressPackageStartupMessages({library(hdWGCNA); library(Seurat); library(WGCNA); library(ggplot2); library(patchwork)}); enableWGCNAThreads(4); set.seed(12345)
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
so <- readRDS("../_data/zeisel_seurat.rds")
so <- SetupForWGCNA(so, gene_select = "fraction", fraction = .25, wgcna_name = "zeisel")
so <- MetacellsByGroups(so, group.by = c("celltype","tissue"), reduction = "pca", k = 20, max_shared = 10, ident.group = "celltype", min_cells = 50)
so <- NormalizeMetacells(so); so <- SetDatExpr(so, group_name = levels(so$celltype), group.by = "celltype", assay = "RNA", layer = "data")
so <- TestSoftPowers(so, networkType = "signed")
ggsave("v1_soft_powers.png", wrap_plots(PlotSoftPowers(so), ncol = 2), width = 9, height = 6, dpi = 130, bg = "white")
so <- ConstructNetwork(so, tom_name = "zeisel", overwrite_tom = TRUE)
png("v2_dendrogram.png", 1400, 700, res = 140); PlotDendrogram(so, main = "hdWGCNA dendrogram"); dev.off()
so <- ModuleEigengenes(so); so <- ModuleConnectivity(so, group.by = "celltype", group_name = levels(so$celltype))
mods <- setdiff(unique(GetModules(so)$module), "grey")
MEs <- GetMEs(so, harmonized = TRUE); MEs <- MEs[, colnames(MEs) != "grey", drop = FALSE]; so@meta.data <- cbind(so@meta.data, MEs)
ggsave("v3_ModuleFeaturePlot.png", wrap_plots(ModuleFeaturePlot(so, features = "hMEs", order = TRUE), ncol = 4), width = 13, height = 3.3 * ceiling(length(mods)/4), dpi = 110, bg = "white", limitsize = FALSE)
ggsave("v4_module_dotplot.png", DotPlot(so, features = colnames(MEs), group.by = "celltype") + RotatedAxis() + scale_color_gradient2(high = "red", mid = "grey95", low = "blue") + ggtitle("Module eigengenes by cell type"), width = 9, height = 4.5, dpi = 140, bg = "white")
so <- RunModuleUMAP(so, n_hubs = 8, n_neighbors = 15, min_dist = .1)
png("v5_ModuleUMAPPlot.png", 1300, 1200, res = 150); ModuleUMAPPlot(so, edge.alpha = .25, sample_edges = TRUE, edge_prop = .1, label_hubs = 2, keep_grey_edges = FALSE); dev.off()
